# Vector clocks capture causality across 3 processes without a shared wall clock.
class VectorClock:
    def __init__(self, n, i):
        self.v = [0] * n
        self.i = i
    def tick(self):
        self.v[self.i] += 1
    def send(self):
        self.tick()
        return list(self.v)
    def recv(self, msg):
        self.v = [max(a, b) for a, b in zip(self.v, msg)]
        self.tick()

def happens_before(a, b):
    return a != b and all(x <= y for x, y in zip(a, b))
def concurrent(a, b):
    return a != b and not happens_before(a, b) and not happens_before(b, a)

P = [VectorClock(3, i) for i in range(3)]
P[0].tick()                 # P0 local event      -> [1,0,0]
msg = P[0].send()           # P0 sends            -> [2,0,0]
P[1].recv(msg)              # P1 receives         -> [2,1,0]
P[2].tick()                 # P2 independent event-> [0,0,1]

a, b, c = [2, 0, 0], [2, 1, 0], [0, 0, 1]
print("send(a) -> recv(b):", happens_before(a, b))   # True: causally ordered
print("a concurrent with c:", concurrent(a, c))      # True: no causal link
print("P1 clock:", P[1].v, " P2 clock:", P[2].v)
assert happens_before(a, b) and concurrent(a, c)
print("vector clocks separate causal from concurrent:", True)

import hashlib, bisect
from collections import Counter

# Consistent hashing: nodes and keys map onto one hash ring. A key belongs to the
# next node clockwise. Adding/removing a node only remaps that node's share of keys,
# not everything -- unlike hash(key) % N. Virtual nodes even out the distribution.
def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16)

class Ring:
    def __init__(self, vnodes=100):
        self.vnodes = vnodes; self.points = []; self.owner = {}
    def add(self, node):
        for v in range(self.vnodes):
            p = h(f"{node}#{v}"); bisect.insort(self.points, p); self.owner[p] = node
    def remove(self, node):
        self.points = [p for p in self.points if self.owner[p] != node]
        self.owner = {p: n for p, n in self.owner.items() if n != node}
    def locate(self, key):
        i = bisect.bisect(self.points, h(key)) % len(self.points)
        return self.owner[self.points[i]]

ring = Ring()
for node in ["A", "B", "C", "D"]:
    ring.add(node)
keys = [f"key{i}" for i in range(10000)]
before = {k: ring.locate(k) for k in keys}
print("distribution:", dict(sorted(Counter(before.values()).items())))

ring.remove("C")
after = {k: ring.locate(k) for k in keys}
moved = sum(before[k] != after[k] for k in keys)
print(f"keys remapped after removing 1 of 4 nodes: {moved/len(keys):.1%} (ideal ~25%)")
assert all(after[k] == before[k] for k in keys if before[k] != "C")
print("only keys owned by the removed node moved:", True)

# A circuit breaker driven by a deterministic timeline (no threads, no wall clock).
# It trips OPEN after repeated failures, REJECTS during a cooldown, then tries a
# HALF-OPEN probe and closes again on success.
class CircuitBreaker:
    def __init__(self, threshold=3, cooldown=5):
        self.state = "closed"; self.fails = 0
        self.threshold = threshold; self.cooldown = cooldown; self.opened_at = None
    def call(self, ok, now):
        if self.state == "open":
            if now - self.opened_at >= self.cooldown:
                self.state = "half-open"          # allow one probe
            else:
                return "rejected"                 # fail fast, don't hammer
        if ok:
            self.state = "closed"; self.fails = 0; return "ok"
        self.fails += 1
        if self.state == "half-open" or self.fails >= self.threshold:
            self.state = "open"; self.opened_at = now
        return "fail"

cb = CircuitBreaker()
timeline = [(0, True), (1, False), (2, False), (3, False), (4, True), (9, True)]
for now, ok in timeline:
    print(f"t={now} -> {cb.call(ok, now):8} state={cb.state}")
assert cb.state == "closed"
print("breaker opened on repeated failures, then recovered:", cb.state == "closed")

import hashlib, bisect

# A sharded + replicated in-memory KV store. Keys are placed by consistent hashing;
# each key is stored on RF replicas. Writes need W acks, reads need R responses and
# take the highest version. R + W > RF keeps reads and writes overlapping, so the
# store stays available and correct while one replica is down.
def h(s):
    return int(hashlib.sha1(s.encode()).hexdigest(), 16)

class Cluster:
    def __init__(self, nodes, rf=3, vnodes=50):
        self.rf = rf
        self.store = {n: {} for n in nodes}       # node -> {key: (version, value)}
        self.down = set()
        self.points = []; self.owner = {}
        for n in nodes:
            for v in range(vnodes):
                p = h(f"{n}#{v}"); bisect.insort(self.points, p); self.owner[p] = n
    def replicas(self, key):                        # RF distinct nodes, clockwise
        out, i = [], bisect.bisect(self.points, h(key))
        while len(out) < self.rf:
            n = self.owner[self.points[i % len(self.points)]]
            if n not in out:
                out.append(n)
            i += 1
        return out
    def put(self, key, value, w):
        reps = self.replicas(key)
        version = 1 + max(self.store[n].get(key, (0, None))[0] for n in reps)
        acks = 0
        for n in reps:
            if n not in self.down:
                self.store[n][key] = (version, value); acks += 1
        return acks >= w, version
    def get(self, key, r):
        reps = self.replicas(key)
        got = [self.store[n][key] for n in reps if n not in self.down and key in self.store[n]]
        if len(got) < r:
            return None, "unavailable (quorum not met)"
        return max(got)[1], f"ok from {len(got)}/{self.rf} replicas"   # newest version wins

c = Cluster(["n1", "n2", "n3", "n4", "n5"], rf=3)
ok, ver = c.put("user:42", "Alice", w=2)
print("put ok:", ok, "version:", ver, "replicas:", c.replicas("user:42"))
print("get:", c.get("user:42", r=2))
c.down.add(c.replicas("user:42")[0])              # one replica fails
val, how = c.get("user:42", r=2)                  # R=2 still met by the other two
print("after one replica down -> get:", val, how)
assert ok and val == "Alice"
print("sharded+replicated KV serves quorum reads with a node down:", val == "Alice")
